import React, { useState, useEffect } from 'react';
import { getDoctors } from '../api/adminApi';

export default function DepartmentFormModal({
  open,
  onClose,
  onSubmit,
  initialData = null, // { departmentName, description, doctorIds }
  loading = false,
}) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [selectedDoctorIds, setSelectedDoctorIds] = useState([]);
  const [allDoctors, setAllDoctors] = useState([]);
  const [loadingDoctors, setLoadingDoctors] = useState(false);

  const isEdit = !!initialData;

  const fetchDoctors = useCallback(async () => {
    setLoadingDoctors(true);
    try {
      // Fetch a large page of doctors for the multi-select
      const res = await getDoctors(0, 100);
      setAllDoctors(res.content || []);
    } catch {
      setAllDoctors([]);
    } finally {
      setLoadingDoctors(false);
    }
  }, []);

  const modalKey = open ? (initialData?.departmentName || 'new') : null;
  const [prevModalKey, setPrevModalKey] = useState(modalKey);

  if (modalKey !== prevModalKey) {
    setPrevModalKey(modalKey);
    if (open) {
      if (initialData) {
        setName(initialData.departmentName || '');
        setDescription(initialData.description || '');
        setSelectedDoctorIds(initialData.doctorIds || []);
      } else {
        setName('');
        setDescription('');
        setSelectedDoctorIds([]);
      }
    }
  }

  useEffect(() => {
    if (open) {
      fetchDoctors();
    }
  }, [open, fetchDoctors]);

  const toggleDoctor = (id) => {
    setSelectedDoctorIds((prev) =>
      prev.includes(id) ? prev.filter((d) => d !== id) : [...prev, id]
    );
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!name.trim()) return;

    if (isEdit) {
      // For update, compute addDoctorIds and removeDoctorIds
      const originalIds = initialData.doctorIds || [];
      const addDoctorIds = selectedDoctorIds.filter(
        (id) => !originalIds.includes(id)
      );
      const removeDoctorIds = originalIds.filter(
        (id) => !selectedDoctorIds.includes(id)
      );
      onSubmit({
        departmentName: name.trim(),
        description: description.trim(),
        addDoctorIds,
        removeDoctorIds,
      });
    } else {
      onSubmit({
        departmentName: name.trim(),
        description: description.trim(),
        doctorIds: selectedDoctorIds,
      });
    }
  };

  if (!open) return null;

  return (
    <div className="admin-modal-overlay" onClick={onClose}>
      <div
        className="admin-modal admin-modal-lg"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="admin-modal-title">
          {isEdit ? 'Edit department' : 'Add department'}
        </div>

        <form onSubmit={handleSubmit}>
          <div className="admin-form-group">
            <label className="admin-form-label">Department name</label>
            <input
              className="admin-form-input"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Cardiology"
              required
            />
          </div>

          <div className="admin-form-group">
            <label className="admin-form-label">Description</label>
            <textarea
              className="admin-form-textarea"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Brief description of the department"
              required
            />
          </div>

          <div className="admin-form-group">
            <label className="admin-form-label">
              Assign doctors{' '}
              <span style={{ fontWeight: 400, color: 'var(--color-text-muted)' }}>
                ({selectedDoctorIds.length} selected)
              </span>
            </label>
            {loadingDoctors ? (
              <div
                className="admin-multi-select"
                style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '20px' }}
              >
                <span style={{ color: 'var(--color-text-muted)', fontSize: '13px' }}>
                  Loading doctors...
                </span>
              </div>
            ) : (
              <div className="admin-multi-select">
                {allDoctors.length === 0 ? (
                  <div
                    style={{
                      padding: '12px',
                      color: 'var(--color-text-muted)',
                      fontSize: '13px',
                      textAlign: 'center',
                    }}
                  >
                    No doctors available
                  </div>
                ) : (
                  allDoctors.map((doc) => (
                    <label key={doc.doctorId} className="admin-multi-option">
                      <input
                        type="checkbox"
                        checked={selectedDoctorIds.includes(doc.doctorId)}
                        onChange={() => toggleDoctor(doc.doctorId)}
                      />
                      <span>
                        Dr. {doc.firstName} {doc.lastName}
                        <span
                          style={{
                            color: 'var(--color-text-muted)',
                            marginLeft: '6px',
                            fontSize: '12px',
                          }}
                        >
                          — {doc.department ? doc.department.departmentName : 'Unassigned'}
                        </span>
                      </span>
                    </label>
                  ))
                )}
              </div>
            )}
          </div>

          <div className="admin-modal-actions">
            <button
              type="button"
              className="admin-btn admin-btn-secondary"
              onClick={onClose}
              disabled={loading}
            >
              Cancel
            </button>
            <button
              type="submit"
              className="admin-btn admin-btn-primary"
              disabled={loading || !name.trim()}
            >
              {loading
                ? isEdit
                  ? 'Saving...'
                  : 'Adding...'
                : isEdit
                ? 'Save changes'
                : 'Add department'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import {
  IconUsers,
  IconStethoscope,
  IconHeartbeat,
  IconBuildingHospital,
  IconCalendarEvent,
  IconClock,
  IconCircleCheck,
  IconCheck,
  IconX,
} from '@tabler/icons-react';
import StatCard from '../components/StatCard';
import StatusPill from '../components/StatusPill';
import { getDashboard, getAppointments } from '../api/adminApi';

export default function AdminDashboard() {
  const [stats, setStats] = useState(null);
  const [recentAppts, setRecentAppts] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchData = React.useCallback(async () => {
    try {
      const [dashData, apptsData] = await Promise.all([
        getDashboard(),
        getAppointments(0, 5),
      ]);
      setStats(dashData);
      setRecentAppts(apptsData.content || []);
    } catch (err) {
      console.error('Dashboard fetch error:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const statCards = stats
    ? [
        {
          icon: <IconHeartbeat size={22} />,
          value: stats.totalPatients,
          label: 'Total patients',
          color: '#E5503E',
          bgColor: '#FDEDEB',
        },
        {
          icon: <IconStethoscope size={22} />,
          value: stats.totalDoctors,
          label: 'Total doctors',
          color: '#3B82F6',
          bgColor: '#EBF2FE',
        },
        {
          icon: <IconBuildingHospital size={22} />,
          value: stats.totalDepartments,
          label: 'Departments',
          color: '#8B5CF6',
          bgColor: '#F0EBFE',
        },
        {
          icon: <IconCalendarEvent size={22} />,
          value: stats.totalAppointments,
          label: 'Total appointments',
          color: '#1D9E75',
          bgColor: '#E6F7F1',
        },
        {
          icon: <IconUsers size={22} />,
          value: stats.totalUsers,
          label: 'Registered users',
          color: '#E5A820',
          bgColor: '#FEF6E0',
        },
      ]
    : [];

  const appointmentStatCards = stats
    ? [
        {
          icon: <IconClock size={22} />,
          value: stats.pendingAppointments,
          label: 'Pending',
          color: '#E5A820',
          bgColor: '#FEF6E0',
        },
        {
          icon: <IconCircleCheck size={22} />,
          value: stats.confirmedAppointments,
          label: 'Confirmed',
          color: '#1D9E75',
          bgColor: '#E6F7F1',
        },
        {
          icon: <IconCheck size={22} />,
          value: stats.completedAppointments,
          label: 'Completed',
          color: '#3B82F6',
          bgColor: '#EBF2FE',
        },
        {
          icon: <IconX size={22} />,
          value: stats.cancelledAppointments,
          label: 'Cancelled',
          color: '#E5503E',
          bgColor: '#FDEDEB',
        },
      ]
    : [];

  return (
    <div className="admin-page">
      <div className="admin-page-header">
        <h1 className="admin-page-title">Dashboard</h1>
        <p className="admin-page-subtitle">
          Overview of your hospital management system
        </p>
      </div>

      {/* Main stat cards */}
      {loading ? (
        <div className="admin-stats-grid">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="admin-stat-card">
              <div
                className="admin-skeleton"
                style={{ width: '44px', height: '44px', borderRadius: '10px' }}
              />
              <div
                className="admin-skeleton"
                style={{ width: '60px', height: '28px' }}
              />
              <div
                className="admin-skeleton"
                style={{ width: '100px', height: '14px' }}
              />
            </div>
          ))}
        </div>
      ) : (
        <div className="admin-stats-grid admin-stats-grid-5">
          {statCards.map((card, i) => (
            <StatCard key={i} {...card} />
          ))}
        </div>
      )}

      {/* Appointment breakdown */}
      {!loading && stats && (
        <>
          <div style={{ marginBottom: '8px', marginTop: '8px' }}>
            <h3
              style={{
                fontSize: '15px',
                fontWeight: 600,
                color: 'var(--color-text-primary)',
                marginBottom: '12px',
              }}
            >
              Appointment breakdown
            </h3>
          </div>
          <div className="admin-stats-grid">
            {appointmentStatCards.map((card, i) => (
              <StatCard key={i} {...card} />
            ))}
          </div>
        </>
      )}

      {/* Recent Appointments Table */}
      <div className="admin-table-wrapper" style={{ marginTop: '8px' }}>
        <div className="admin-table-header">
          <div className="admin-table-title">Recent appointments</div>
        </div>

        {loading ? (
          <>
            {Array.from({ length: 5 }).map((_, i) => (
              <div key={i} className="admin-skeleton-row">
                <div className="admin-skeleton admin-skeleton-circle" />
                <div
                  className="admin-skeleton admin-skeleton-line"
                  style={{ width: '120px', flex: 1 }}
                />
                <div
                  className="admin-skeleton admin-skeleton-line"
                  style={{ width: '80px' }}
                />
                <div
                  className="admin-skeleton admin-skeleton-line"
                  style={{ width: '60px' }}
                />
              </div>
            ))}
          </>
        ) : recentAppts.length === 0 ? (
          <div className="admin-empty">
            <IconCalendarEvent size={48} />
            <div className="admin-empty-title">No appointments yet</div>
            <div className="admin-empty-text">
              Appointments will appear here once created.
            </div>
          </div>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Patient</th>
                  <th>Doctor</th>
                  <th>Date</th>
                  <th>Time</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {recentAppts.map((appt, i) => {
                  // Handle both flat DTO and nested entity shapes
                  const patientName =
                    appt.patientName ||
                    (appt.patient?.user
                      ? `${appt.patient.user.firstName || ''} ${appt.patient.user.lastName || ''}`
                      : '—');
                  const doctorName =
                    appt.doctorName ||
                    (appt.doctor?.user
                      ? `Dr. ${appt.doctor.user.firstName || ''} ${appt.doctor.user.lastName || ''}`
                      : `Doctor #${appt.doctorId || '—'}`);
                  const date = appt.appointmentDate || '—';
                  const time =
                    appt.appointmentTime || appt.startTime || '—';
                  const status = appt.status || '—';

                  return (
                    <tr key={appt.appointmentId || i}>
                      <td>
                        <div className="admin-cell-user">
                          <div
                            className="admin-cell-avatar"
                            style={{ background: '#8B5CF6' }}
                          >
                            {typeof patientName === 'string'
                              ? patientName.charAt(0).toUpperCase()
                              : '?'}
                          </div>
                          <span className="admin-cell-name">{patientName}</span>
                        </div>
                      </td>
                      <td>{doctorName}</td>
                      <td>{date}</td>
                      <td>{time}</td>
                      <td>
                        <StatusPill status={status} />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

