import { useState, useEffect, useCallback } from 'react';
import { IconSearch, IconPill, IconX } from '@tabler/icons-react';
import api from '../api';
import toast from 'react-hot-toast';

// ─── palette tokens ───────────────────────────────────────────────────
const T = {
  navy:   '#0B1F3F',
  teal:   '#1D9E75',
  muted:  '#9FB3D4',
  sec:    '#6B7690',
  hair:   '#ECEEF3',
};

// ─── Medicine Detail Modal ────────────────────────────────────────────
function MedicineDetailModal({ medicineId, onClose }) {
  const [status, setStatus]   = useState('loading'); // loading | ok | error
  const [detail, setDetail]   = useState(null);

  const fetchDetail = useCallback(async () => {
    try {
      const res = await api.get(`/admin/medicines/${medicineId}`);
      setDetail(res.data);
      setStatus('ok');
    } catch {
      setStatus('error');
    }
  }, [medicineId]);

  useEffect(() => { fetchDetail(); }, [fetchDetail]);

  // Close on Escape key
  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onClose]);

  // ── shared label style ──────────────────────────────────────────────
  const lbl = {
    fontSize: '11px', fontWeight: 600, color: T.muted,
    textTransform: 'uppercase', letterSpacing: '0.45px', marginBottom: '4px',
  };
  const val = {
    fontSize: '14px', color: T.navy, fontWeight: 400,
  };

  return (
    /* Overlay */
    <div
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
      style={{
        position: 'fixed', inset: 0,
        background: 'rgba(11,31,63,0.45)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        zIndex: 1000,
        padding: '16px',
      }}
    >
      {/* Modal */}
      <div style={{
        width: '420px', maxWidth: '100%',
        background: '#FFFFFF', borderRadius: '14px',
        padding: '24px',
        boxShadow: '0 16px 48px rgba(11,31,63,0.22)',
        position: 'relative',
        maxHeight: '90vh',
        overflowY: 'auto',
      }}>

        {/* Close button */}
        <button
          onClick={onClose}
          style={{
            position: 'absolute', top: '16px', right: '16px',
            background: 'none', border: 'none',
            cursor: 'pointer', color: T.sec, padding: '4px',
            display: 'flex', alignItems: 'center',
          }}
        >
          <IconX size={18} />
        </button>

        {/* ── LOADING ──────────────────────────────────────────── */}
        {status === 'loading' && (
          <div style={{ textAlign: 'center', padding: '32px 0' }}>
            <div style={{
              width: 36, height: 36, border: `3px solid ${T.hair}`,
              borderTopColor: T.teal, borderRadius: '50%',
              animation: 'spin 0.7s linear infinite',
              margin: '0 auto 16px',
            }} />
            <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
            <div style={{ fontSize: '13px', color: T.sec }}>Loading medicine details…</div>
          </div>
        )}

        {/* ── ERROR ────────────────────────────────────────────── */}
        {status === 'error' && (
          <div style={{ textAlign: 'center', padding: '24px 0' }}>
            <IconPill size={36} color={T.muted} style={{ marginBottom: '12px' }} />
            <div style={{ fontSize: '14px', fontWeight: 500, color: T.navy, marginBottom: '6px' }}>
              Couldn't load medicine details.
            </div>
            <div style={{ fontSize: '12px', color: T.sec, marginBottom: '20px' }}>
              The server returned an error. Please try again.
            </div>
            <button
              onClick={fetchDetail}
              style={{
                background: T.teal, color: '#fff', border: 'none',
                borderRadius: '8px', padding: '9px 20px',
                fontSize: '13px', fontWeight: 600, cursor: 'pointer',
                marginRight: '8px',
              }}
            >
              Retry
            </button>
            <button
              onClick={onClose}
              style={{
                background: '#fff', color: T.sec,
                border: `1px solid ${T.hair}`, borderRadius: '8px',
                padding: '9px 20px', fontSize: '13px', cursor: 'pointer',
              }}
            >
              Close
            </button>
          </div>
        )}

        {/* ── DETAIL ───────────────────────────────────────────── */}
        {status === 'ok' && detail && (
          <>
            {/* Header */}
            <div style={{ paddingRight: '28px', marginBottom: '10px' }}>
              <div style={{ fontSize: '18px', fontWeight: 500, color: T.navy, lineHeight: 1.3 }}>
                {detail.medicineName || '—'}
              </div>
              <div style={{ fontSize: '13px', color: T.sec, marginTop: '3px' }}>
                {[detail.genericName, detail.strength ? `(${detail.strength})` : ''].filter(Boolean).join(' ') || '—'}
              </div>
            </div>

            {/* Status pill */}
            <div style={{ marginBottom: '16px' }}>
              {detail.isActive
                ? (
                  <span style={{
                    display: 'inline-flex', alignItems: 'center', gap: '5px',
                    background: '#E1F5EE', color: '#085041',
                    borderRadius: '20px', padding: '3px 11px',
                    fontSize: '12px', fontWeight: 500,
                  }}>
                    <span style={{ width: 6, height: 6, borderRadius: '50%', background: T.teal, display: 'inline-block' }} />
                    Active
                  </span>
                ) : (
                  <span style={{
                    display: 'inline-flex', alignItems: 'center', gap: '5px',
                    background: '#F1F3F7', color: T.sec,
                    borderRadius: '20px', padding: '3px 11px',
                    fontSize: '12px', fontWeight: 500,
                  }}>
                    <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#B0B8C9', display: 'inline-block' }} />
                    Inactive
                  </span>
                )}
            </div>

            {/* Divider */}
            <div style={{ borderTop: `1px solid ${T.hair}`, marginBottom: '18px' }} />

            {/* 2-col detail grid */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              rowGap: '16px',
              columnGap: '20px',
              marginBottom: '24px',
            }}>
              <div>
                <div style={lbl}>Generic name</div>
                <div style={val}>{detail.genericName || '—'}</div>
              </div>
              <div>
                <div style={lbl}>Strength</div>
                <div style={val}>{detail.strength || '—'}</div>
              </div>
              <div>
                <div style={lbl}>Dosage form</div>
                <div style={val}>{detail.dosageForm || '—'}</div>
              </div>
              <div>
                <div style={lbl}>Manufacturer</div>
                <div style={val}>{detail.manufacturer || '—'}</div>
              </div>
            </div>

            {/* Close button */}
            <button
              onClick={onClose}
              style={{
                width: '100%', background: T.teal, color: '#fff',
                border: 'none', borderRadius: '8px', padding: '11px',
                fontSize: '14px', fontWeight: 600, cursor: 'pointer',
              }}
            >
              Close
            </button>
          </>
        )}
      </div>
    </div>
  );
}

// ─── Main page component ──────────────────────────────────────────────
export default function DoctorMedicines({ selectedId: propSelectedId, onSelect: propOnSelect }) {
  const [data, setData] = useState([]);
  const [page, setPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [totalElements, setTotalElements] = useState(0);
  const [loading, setLoading] = useState(true);

  // Search state
  const [keyword, setKeyword] = useState('');
  const [debouncedKeyword, setDebouncedKeyword] = useState('');

  // Modal state — only used when this page is NOT a picker
  const [modalId, setModalId] = useState(null);

  // Picker selection state (local state if uncontrolled)
  const isControlled = propSelectedId !== undefined;
  const selectedId = isControlled ? propSelectedId : null;

  const size = 20;

  // Debounce keyword change (300ms) and reset page to 0
  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedKeyword(keyword);
      setPage(0);
    }, 300);
    return () => clearTimeout(handler);
  }, [keyword]);

  const fetchMedicines = useCallback(async () => {
    try {
      const endpoint = debouncedKeyword ? '/doctor/medicines/search' : '/doctor/medicines';
      const params = {
        page,
        size,
        ...(debouncedKeyword && { keyword: debouncedKeyword }),
      };
      const res = await api.get(endpoint, { params });
      setData(res.data?.content || []);
      setTotalPages(res.data?.totalPages || 0);
      setTotalElements(res.data?.totalElements || 0);
    } catch {
      toast.error('Failed to load medicine catalog');
    } finally {
      setLoading(false);
    }
  }, [page, debouncedKeyword]);

  useEffect(() => { fetchMedicines(); }, [fetchMedicines]);

  const handleCardClick = (id) => {
    if (propOnSelect) {
      // Picker mode — delegate to parent
      propOnSelect(id);
    } else {
      // Standalone catalog mode — open detail modal
      setModalId(id);
    }
  };

  const start = page * size + 1;
  const end   = Math.min((page + 1) * size, totalElements);

  return (
    <div style={{ paddingBottom: '40px' }}>
      <div className="page-header">
        <div>
          <h2>Medicines Catalog</h2>
          <p>Search and view active medicines for prescriptions</p>
        </div>
      </div>

      {/* Search Bar */}
      <div className="search-box-wrap" style={{ maxWidth: '400px', width: '100%', marginBottom: '20px' }}>
        <IconSearch size={18} />
        <input
          type="text"
          placeholder="Search medicines (e.g. paracetamol)"
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
        />
      </div>

      {loading ? (
        <div className="medicine-grid">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div
              key={i}
              className="card"
              style={{
                height: '110px', padding: '14px', borderRadius: '12px',
                border: '0.5px solid var(--border)',
                background: 'linear-gradient(90deg, #f9fafc 25%, #f4f6fa 50%, #f9fafc 75%)',
                backgroundSize: '200% 100%', animation: 'shimmer 1.5s infinite',
              }}
            />
          ))}
        </div>
      ) : data.length === 0 ? (
        <div className="card" style={{ padding: '40px', textAlign: 'center', marginTop: '16px' }}>
          <IconPill size={40} color="var(--text-secondary)" style={{ marginBottom: '12px' }} />
          <h3 style={{ margin: '0 0 4px', fontSize: '16px', fontWeight: 600 }}>No Medicines Found</h3>
          <p style={{ margin: 0, fontSize: '13px', color: 'var(--text-secondary)' }}>
            {debouncedKeyword
              ? `No medicines found for '${debouncedKeyword}'`
              : 'No active medicines available.'}
          </p>
        </div>
      ) : (
        <>
          {/* Responsive grid */}
          <div className="medicine-grid">
            {data.map((medicine) => {
              const isSelected = selectedId === medicine.medicineId;
              return (
                <div
                  key={medicine.medicineId}
                  className={`card medicine-card ${isSelected ? 'selected' : ''}`}
                  onClick={() => handleCardClick(medicine.medicineId)}
                  title="Click to view details"
                  style={{
                    padding: '14px', borderRadius: '12px',
                    border: '0.5px solid var(--border)',
                    background: 'var(--card)',
                    display: 'flex', flexDirection: 'column', justifyContent: 'space-between',
                    minHeight: '110px', cursor: 'pointer',
                    transition: 'all 0.2s ease',
                    ...(isSelected && { borderColor: 'var(--teal)', backgroundColor: '#F0F7FB' }),
                  }}
                >
                  <div>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', color: 'var(--navy)', marginBottom: '4px' }}>
                      {medicine.medicineName}
                    </div>
                    <div style={{ fontSize: '12px', color: 'var(--text-secondary)', marginBottom: '8px' }}>
                      {medicine.genericName || '—'} {medicine.strength ? `(${medicine.strength})` : ''}
                    </div>
                  </div>
                  <div style={{
                    fontSize: '11px', color: 'var(--text-secondary)',
                    borderTop: '0.5px solid var(--border)', paddingTop: '8px',
                    display: 'flex', justifyContent: 'space-between',
                  }}>
                    <span>{medicine.dosageForm || '—'}</span>
                    <span>{medicine.manufacturer || '—'}</span>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Pagination */}
          {totalPages > 0 && (
            <div className="doctor-pagination">
              <div className="doctor-pagination-info">
                Showing {start}–{end} of {totalElements}
              </div>
              <div className="doctor-pagination-buttons">
                <button
                  className="doctor-pagination-btn"
                  disabled={page <= 0}
                  onClick={() => setPage(page - 1)}
                >
                  Prev
                </button>
                <button
                  className="doctor-pagination-btn"
                  disabled={page >= totalPages - 1}
                  onClick={() => setPage(page + 1)}
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </>
      )}

      {/* Detail modal — rendered at top of component tree via portal would be ideal,
          but inline conditional is fine here since it uses position:fixed */}
      {modalId !== null && (
        <MedicineDetailModal
          medicineId={modalId}
          onClose={() => setModalId(null)}
        />
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { IconEdit, IconX } from '@tabler/icons-react';
import { useOutletContext } from 'react-router-dom';
import api from '../api';
import PhotoUpload from '../../patient/components/PhotoUpload';
import toast from 'react-hot-toast';

const AVAILABILITY_OPTIONS = [
  { value: 'AVAILABLE',     label: 'Available' },
  { value: 'NOT_AVAILABLE', label: 'Not Available' },
  { value: 'ON_LEAVE',      label: 'On Leave' },
];

// Only the fields updateMyProfile() on the backend actually persists.
const EDITABLE = [
  'firstName', 'lastName', 'phoneNumber',
  'description', 'availabilityStatus', 'profilePhoto',
];

export default function DoctorProfile() {
  const { profile, setProfile } = useOutletContext();
  const [editing, setEditing]   = useState(false);
  const [form, setForm]         = useState({});
  const [saving, setSaving]     = useState(false);

  const [prevProfile, setPrevProfile] = useState(null);
  if (profile && profile !== prevProfile) {
    setPrevProfile(profile);
    const snap = {};
    EDITABLE.forEach((k) => { snap[k] = profile[k] ?? ''; });
    setForm(snap);
  }

  if (!profile) {
    return (
      <div style={{ display: 'flex', gap: '24px', padding: '4px', maxWidth: '1020px', margin: '0 auto' }}>
        <div className="skeleton" style={{ width: '230px', height: '360px', borderRadius: '12px' }} />
        <div className="skeleton" style={{ flex: 1, height: '360px', borderRadius: '12px' }} />
      </div>
    );
  }

  const set = (field) => (e) => setForm({ ...form, [field]: e.target.value });

  const handleCancel = () => {
    const snap = {};
    EDITABLE.forEach((k) => { snap[k] = profile[k] ?? ''; });
    setForm(snap);
    setEditing(false);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const changed = {};
      EDITABLE.forEach((k) => {
        if (String(form[k] ?? '') !== String(profile[k] ?? '')) {
          changed[k] = form[k];
        }
      });
      if (!Object.keys(changed).length) {
        toast('Nothing to save', { icon: 'ℹ️' });
        setEditing(false);
        setSaving(false);
        return;
      }
      const res = await api.put('/doctor/profile', changed);
      setProfile((p) => ({ ...p, ...changed }));
      toast.success(res.data?.message || 'Profile updated successfully');
      setEditing(false);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to update profile');
    } finally {
      setSaving(false);
    }
  };

  const initials =
    `${(profile.firstName || '?')[0]}${(profile.lastName || '')[0] || ''}`.toUpperCase();

  const currentPhoto = editing
    ? form.profilePhoto || ''
    : profile.profilePhoto || '';

  const deptName =
    profile.department?.departmentName ||
    profile.departmentName ||
    (typeof profile.department === 'string' ? profile.department : '') ||
    '';

  const displayStatus = editing
    ? (form.availabilityStatus || 'AVAILABLE')
    : (profile.availabilityStatus || 'AVAILABLE');

  const statusLabel =
    AVAILABILITY_OPTIONS.find((o) => o.value === displayStatus)?.label || displayStatus;

  // ── shared micro-styles ────────────────────────────────────────────
  const cardStyle = {
    background: '#FFFFFF',
    borderRadius: '12px',
    border: '0.5px solid #E2E6ED',
    boxShadow: '0 1px 3px rgba(11,31,63,0.04)',
  };

  const kvRowStyle = {
    display: 'flex',
    justifyContent: 'space-between',
    padding: '8px 0',
    fontSize: '12px',
    borderTop: '1px solid #EDEFF3',
  };

  const fieldLabelStyle = {
    display: 'block',
    fontSize: '11px',
    fontWeight: 600,
    color: '#8C96AD',
    textTransform: 'uppercase',
    letterSpacing: '0.45px',
    marginBottom: '4px',
  };

  const fieldValueStyle = {
    fontSize: '14px',
    color: '#0B1F3F',
    fontWeight: 400,
    paddingBottom: '10px',
    borderBottom: '1px solid #EDEFF3',
  };

  // ── render ─────────────────────────────────────────────────────────
  return (
    <div style={{ maxWidth: '1020px', margin: '0 auto' }}>
      <div style={{ display: 'flex', gap: '24px', alignItems: 'flex-start', flexWrap: 'wrap' }}>

        {/* ─── LEFT SUMMARY CARD ─────────────────────────────── */}
        <div style={{ ...cardStyle, width: '230px', padding: '20px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>

          {/* Avatar */}
          <PhotoUpload
            value={currentPhoto}
            onChange={(url) => setForm({ ...form, profilePhoto: url })}
            isEditing={editing}
            initials={initials}
            size={64}
          />

          {/* Name */}
          <div style={{ fontSize: '16px', fontWeight: 500, color: '#0B1F3F', marginTop: '12px', textAlign: 'center' }}>
            {editing
              ? `${form.firstName || ''} ${form.lastName || ''}`.trim() || '—'
              : `${profile.firstName || ''} ${profile.lastName || ''}`.trim() || '—'}
          </div>

          {/* Email */}
          <div style={{ fontSize: '12px', color: '#9FB3D4', marginTop: '3px', textAlign: 'center', wordBreak: 'break-all' }}>
            {profile.email || '—'}
          </div>

          {/* Availability pill */}
          <div style={{ marginTop: '12px', marginBottom: '16px' }}>
            {editing ? (
              <select
                value={form.availabilityStatus}
                onChange={set('availabilityStatus')}
                style={{
                  background: '#E1F5EE', color: '#085041',
                  border: 'none', borderRadius: '20px',
                  padding: '3px 11px', fontSize: '12px', fontWeight: 500,
                  cursor: 'pointer', outline: 'none',
                }}
              >
                {AVAILABILITY_OPTIONS.map((o) => (
                  <option key={o.value} value={o.value}>{o.label}</option>
                ))}
              </select>
            ) : (
              <span style={{
                display: 'inline-flex', alignItems: 'center', gap: '5px',
                background: '#E1F5EE', color: '#085041',
                borderRadius: '20px', padding: '3px 11px',
                fontSize: '12px', fontWeight: 500,
              }}>
                <span style={{
                  width: 7, height: 7, borderRadius: '50%',
                  background: '#1D9E75', display: 'inline-block',
                }} />
                {statusLabel}
              </span>
            )}
          </div>

          {/* Key-value rows */}
          <div style={{ width: '100%', borderTop: '1px solid #EDEFF3' }}>
            <div style={kvRowStyle}>
              <span style={{ color: '#9FB3D4' }}>Phone</span>
              <span style={{ fontWeight: 600, color: '#0B1F3F', fontSize: '12px' }}>
                {(editing ? form.phoneNumber : profile.phoneNumber) || '—'}
              </span>
            </div>
            <div style={kvRowStyle}>
              <span style={{ color: '#9FB3D4' }}>Department</span>
              <span style={{ fontWeight: 600, color: '#0B1F3F', fontSize: '12px', textAlign: 'right', maxWidth: '120px' }}>
                {deptName || '—'}
              </span>
            </div>
            <div style={{ ...kvRowStyle, borderBottom: 'none' }}>
              <span style={{ color: '#9FB3D4' }}>Room</span>
              <span style={{ fontWeight: 600, color: '#0B1F3F', fontSize: '12px' }}>
                {profile.roomNumber || '—'}
              </span>
            </div>
          </div>
        </div>

        {/* ─── RIGHT DETAILS CARD ─────────────────────────────── */}
        <div style={{ ...cardStyle, flex: 1, minWidth: '320px', padding: '22px' }}>

          {/* Header row */}
          <div style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            paddingBottom: '16px',
            borderBottom: '1px solid #EDEFF3',
            marginBottom: '20px',
          }}>
            <div>
              <div style={{ fontSize: '15px', fontWeight: 600, color: '#0B1F3F', margin: 0 }}>
                Professional details
              </div>
              <div style={{ fontSize: '12px', color: '#9FB3D4', marginTop: '3px' }}>
                Keep your information up to date
              </div>
            </div>

            {!editing ? (
              <button
                onClick={() => setEditing(true)}
                style={{
                  background: '#1D9E75', color: '#fff', border: 'none',
                  borderRadius: '8px', padding: '8px 16px',
                  fontSize: '13px', fontWeight: 600,
                  display: 'inline-flex', alignItems: 'center', gap: '6px',
                  cursor: 'pointer',
                }}
              >
                <IconEdit size={15} /> Edit profile
              </button>
            ) : (
              <div style={{ display: 'flex', gap: '8px' }}>
                <button
                  onClick={handleCancel} disabled={saving}
                  style={{
                    background: '#fff', color: '#6B7690',
                    border: '1px solid #E2E6ED', borderRadius: '8px',
                    padding: '8px 16px', fontSize: '13px', fontWeight: 500,
                    display: 'inline-flex', alignItems: 'center', gap: '5px',
                    cursor: 'pointer', opacity: saving ? 0.5 : 1,
                  }}
                >
                  <IconX size={14} /> Cancel
                </button>
                <button
                  onClick={handleSave} disabled={saving}
                  style={{
                    background: '#1D9E75', color: '#fff', border: 'none',
                    borderRadius: '8px', padding: '8px 16px',
                    fontSize: '13px', fontWeight: 600,
                    display: 'inline-flex', alignItems: 'center', gap: '6px',
                    cursor: saving ? 'not-allowed' : 'pointer',
                    opacity: saving ? 0.6 : 1,
                  }}
                >
                  {saving
                    ? <><span className="spinner" style={{ width: 13, height: 13 }} /> Saving…</>
                    : 'Save changes'}
                </button>
              </div>
            )}
          </div>

          {/* ── EDITABLE FIELDS ─────────────────────────────── */}
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            rowGap: '14px',
            columnGap: '20px',
            marginBottom: '20px',
          }}>
            {/* First name */}
            <div>
              <span style={fieldLabelStyle}>First name</span>
              {editing
                ? <input className="form-input" value={form.firstName || ''} onChange={set('firstName')} style={{ height: '36px', marginBottom: 0 }} />
                : <div style={fieldValueStyle}>{profile.firstName || '—'}</div>}
            </div>

            {/* Last name */}
            <div>
              <span style={fieldLabelStyle}>Last name</span>
              {editing
                ? <input className="form-input" value={form.lastName || ''} onChange={set('lastName')} style={{ height: '36px', marginBottom: 0 }} />
                : <div style={fieldValueStyle}>{profile.lastName || '—'}</div>}
            </div>

            {/* Phone — editable in both modes via input/display */}
            <div style={{ gridColumn: editing ? '1 / -1' : undefined }}>
              <span style={fieldLabelStyle}>Phone</span>
              {editing
                ? <input className="form-input" value={form.phoneNumber || ''} onChange={set('phoneNumber')} style={{ height: '36px', marginBottom: 0 }} />
                : <div style={fieldValueStyle}>{profile.phoneNumber || '—'}</div>}
            </div>

            {/* Read-only fields — plain display when NOT editing */}
            {!editing && (
              <>
                <div>
                  <span style={fieldLabelStyle}>Specialization</span>
                  <div style={fieldValueStyle}>{profile.specialization || '—'}</div>
                </div>
                <div>
                  <span style={fieldLabelStyle}>Qualification</span>
                  <div style={fieldValueStyle}>{profile.qualification || '—'}</div>
                </div>
                <div>
                  <span style={fieldLabelStyle}>Years of experience</span>
                  <div style={fieldValueStyle}>
                    {profile.yearsOfExperience != null ? `${profile.yearsOfExperience} yrs` : '—'}
                  </div>
                </div>
                <div>
                  <span style={fieldLabelStyle}>Consultation fee</span>
                  <div style={fieldValueStyle}>
                    {profile.consultationFee != null ? `₹${profile.consultationFee}` : '—'}
                  </div>
                </div>
              </>
            )}
          </div>

          {/* ── READ-ONLY BLOCK (edit mode only) ─────────────── */}
          {editing && (
            <div style={{
              background: '#F7F9FC',
              borderRadius: '10px',
              border: '0.5px solid #E2E6ED',
              padding: '14px 16px',
              marginBottom: '20px',
            }}>
              <div style={{
                fontSize: '11px', fontWeight: 600,
                color: '#8C96AD', textTransform: 'uppercase',
                letterSpacing: '0.45px', marginBottom: '12px',
                display: 'flex', alignItems: 'center', gap: '6px',
              }}>
                <span style={{
                  display: 'inline-block', width: 6, height: 6,
                  borderRadius: '50%', background: '#9FB3D4',
                }} />
                Read-only · managed by admin
              </div>
              <div style={{
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                rowGap: '12px',
                columnGap: '20px',
              }}>
                {[
                  ['Specialization', profile.specialization],
                  ['Qualification', profile.qualification],
                  ['Years of experience', profile.yearsOfExperience != null ? `${profile.yearsOfExperience} yrs` : null],
                  ['Consultation fee', profile.consultationFee != null ? `₹${profile.consultationFee}` : null],
                ].map(([label, val]) => (
                  <div key={label}>
                    <div style={{ fontSize: '11px', color: '#8C96AD', marginBottom: '3px' }}>{label}</div>
                    <div style={{ fontSize: '13px', color: '#0B1F3F' }}>{val || '—'}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* About section */}
          <div style={{ borderTop: '1px solid #EDEFF3', paddingTop: '20px' }}>
            <span style={{ ...fieldLabelStyle, display: 'block', marginBottom: '10px' }}>About</span>
            {editing ? (
              <textarea
                value={form.description || ''}
                onChange={set('description')}
                style={{
                  width: '100%', minHeight: '80px',
                  padding: '10px 12px',
                  border: '1px solid #E2E6ED', borderRadius: '8px',
                  fontSize: '13px', lineHeight: '1.6',
                  color: '#0B1F3F', resize: 'none', outline: 'none',
                  fontFamily: "'Inter', system-ui, sans-serif",
                  boxSizing: 'border-box',
                }}
              />
            ) : (
              <div style={{ fontSize: '13px', color: '#6B7690', lineHeight: '1.7', whiteSpace: 'pre-line' }}>
                {profile.description || 'No description added yet.'}
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { IconCamera } from '@tabler/icons-react';
import toast from 'react-hot-toast';
import axios from 'axios';

const getBackendUrl = () => {
  const host =
    typeof window !== 'undefined' && window.location.hostname
      ? window.location.hostname
      : 'localhost';
  return `http://${host}:8080`;
};

export default function PhotoUpload({
  value,
  onChange,
  isEditing,
  initials,
  size = 76,
}) {
  const [uploading, setUploading] = useState(false);
  const [localPreview, setLocalPreview] = useState(null);
  const [imgError, setImgError] = useState(false);
  const fileInputRef = useRef(null);

  const [prevDisplay, setPrevDisplay] = useState({ value, localPreview });

  if (prevDisplay.value !== value || prevDisplay.localPreview !== localPreview) {
    setPrevDisplay({ value, localPreview });
    setImgError(false);
  }

  const handleFileChange = async (e) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];

    // Client-side validations
    if (!file.type.startsWith('image/')) {
      toast.error('Only image files are allowed');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error('File size must be under 5MB');
      return;
    }

    // Set immediate local preview
    const previewUrl = URL.createObjectURL(file);
    setLocalPreview(previewUrl);
    setImgError(false);
    setUploading(true);

    const formData = new FormData();
    formData.append('file', file);

    const previousValue = value;
    const token = localStorage.getItem('token');
    const headers = {
      'Content-Type': 'multipart/form-data',
    };
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    try {
      const res = await axios.post(
        `${getBackendUrl()}/api/upload/image`,
        formData,
        { headers }
      );
      if (res.data && res.data.url) {
        onChange(res.data.url);
      } else {
        throw new Error('No URL returned from server');
      }
    } catch (err) {
      toast.error(
        err.response?.data?.message ||
          err.response?.data?.error ||
          'Failed to upload image'
      );
      setLocalPreview(null);
      onChange(previousValue);
    } finally {
      setUploading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleRemove = () => {
    setLocalPreview(null);
    setImgError(false);
    onChange('');
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const displayPhoto = localPreview || value;
  const showImage = Boolean(displayPhoto) && !imgError;

  return (
    <div
      style={{
        display: 'inline-flex',
        flexDirection: 'column',
        alignItems: 'center',
      }}
    >
      <div
        className="profile-avatar-wrap"
        style={{ position: 'relative', width: `${size}px`, height: `${size}px` }}
      >
        <div
          className="profile-avatar"
          style={{
            width: `${size}px`,
            height: `${size}px`,
            borderRadius: '50%',
            background: 'var(--color-status-blue-bg, #E6F1FB)',
            color: 'var(--color-status-blue, #0C447C)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: `${Math.round(size * 0.32)}px`,
            fontWeight: '600',
            overflow: 'hidden',
            position: 'relative',
          }}
        >
          {showImage ? (
            <img
              src={displayPhoto}
              alt=""
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              onError={() => setImgError(true)}
            />
          ) : (
            initials || '—'
          )}

          {uploading && (
            <div
              style={{
                position: 'absolute',
                inset: 0,
                background: 'rgba(0,0,0,0.4)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <span className="spinner" style={{ width: '20px', height: '20px' }} />
            </div>
          )}
        </div>

        {isEditing && !uploading && (
          <div
            className="avatar-camera-badge"
            style={{
              position: 'absolute',
              bottom: '0',
              right: '0',
              width: '26px',
              height: '26px',
              borderRadius: '50%',
              background: 'var(--color-teal, #1D9E75)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              border: '2px solid #fff',
              cursor: 'pointer',
              color: '#fff',
              boxShadow: '0 2px 4px rgba(0,0,0,0.15)',
              transition: 'transform 0.15s ease',
            }}
            title="Upload photo"
            onClick={() => fileInputRef.current?.click()}
          >
            <IconCamera size={14} />
          </div>
        )}
      </div>

      {isEditing && (
        <input
          type="file"
          ref={fileInputRef}
          accept="image/*"
          style={{ display: 'none' }}
          onChange={handleFileChange}
        />
      )}

      {isEditing && (localPreview || value) && !uploading && (
        <button
          type="button"
          onClick={handleRemove}
          style={{
            background: 'none',
            border: 'none',
            color: '#791F1F',
            fontSize: '11px',
            fontWeight: '500',
            cursor: 'pointer',
            marginTop: '6px',
            padding: 0,
            textDecoration: 'underline',
          }}
        >
          Remove photo
        </button>
      )}
    </div>
  );
}

