import { useState, useEffect } from 'react';
import { IconEdit, IconX } from '@tabler/icons-react';
import toast from 'react-hot-toast';
import { getProfile, updatePatientDetails } from '../api/patientApi';
import PhotoUpload from '../components/PhotoUpload';

const BLOOD_GROUPS = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];

export default function MyProfilePage() {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({});
  const [saving, setSaving] = useState(false);

  const email = localStorage.getItem('userEmail');

  const fetchProfile = useCallback(async () => {
    try {
      const data = await getProfile(email);
      setProfile(data);
      setForm(data);
    } catch {
      toast.error('Failed to load profile');
    } finally {
      setLoading(false);
    }
  }, [email]);

  useEffect(() => {
    fetchProfile();
  }, [fetchProfile]);

  const handleEdit = () => setEditing(true);
  const handleCancel = () => {
    setForm(profile);
    setEditing(false);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      // Build partial update — only send changed fields + email
      const payload = { email };
      const fields = [
        'firstName',
        'lastName',
        'address',
        'phoneNumber',
        'dob',
        'profilephoto',
        'profilePhoto',
        'description',
        'bloodGroup',
        'emergencyContactName',
        'emergencyContactNumber',
        'emergencyContactRelation',
      ];
      fields.forEach((f) => {
        if (form[f] !== profile[f] && form[f] !== undefined) {
          payload[f] = form[f];
        }
      });

      const res = await updatePatientDetails(payload);
      toast.success(res.message || 'Profile updated successfully!');
      await fetchProfile();
      setEditing(false);
    } catch (err) {
      toast.error(
        err.response?.data?.message || 'Failed to update profile'
      );
    } finally {
      setSaving(false);
    }
  };

  const set = (field) => (e) => setForm({ ...form, [field]: e.target.value });

  if (loading) {
    return (
      <div style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto' }}>
        <div style={{ display: 'flex', gap: '24px' }}>
          <div
            className="skeleton"
            style={{ width: '260px', height: '340px', borderRadius: '12px' }}
          />
          <div
            className="skeleton"
            style={{ flex: 1, height: '340px', borderRadius: '12px' }}
          />
        </div>
      </div>
    );
  }

  if (!profile) return null;

  const initials =
    `${(profile.firstName || '?')[0]}${(profile.lastName || '')[0] || ''}`.toUpperCase();

  const currentPhoto = editing
    ? form.profilePhoto || form.profilephoto
    : profile.profilePhoto || profile.profilephoto;

  return (
    <div style={{ maxWidth: '1020px', margin: '0 auto' }}>
      {/* ─── Page Container Layout ─────────────────── */}
      <div
        style={{
          display: 'flex',
          gap: '24px',
          alignItems: 'flex-start',
          flexWrap: 'wrap',
        }}
      >
        {/* ─── LEFT SUMMARY CARD ───────────────────── */}
        <div
          style={{
            width: '260px',
            background: '#FFFFFF',
            borderRadius: '12px',
            border: '0.5px solid var(--color-border, #E8ECF1)',
            padding: '24px 20px',
            boxShadow: '0 1px 3px rgba(0,0,0,0.04)',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
          }}
        >
          {/* Photo Avatar */}
          <PhotoUpload
            value={currentPhoto}
            onChange={(url) =>
              setForm({ ...form, profilePhoto: url, profilephoto: url })
            }
            isEditing={editing}
            initials={initials}
            size={84}
          />

          {/* Full Name */}
          <h3
            style={{
              fontSize: '16px',
              fontWeight: 700,
              color: 'var(--color-navy, #0B1F3F)',
              margin: '14px 0 2px',
              textAlign: 'center',
            }}
          >
            {editing ? `${form.firstName || ''} ${form.lastName || ''}` : `${profile.firstName || ''} ${profile.lastName || ''}`}
          </h3>

          {/* Email */}
          <p
            style={{
              fontSize: '12px',
              color: 'var(--color-text-secondary, #6B7A99)',
              margin: '0 0 12px',
              textAlign: 'center',
              wordBreak: 'break-all',
            }}
          >
            {profile.email}
          </p>

          {/* Status Pill */}
          <div style={{ marginBottom: '18px' }}>
            <span
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '5px',
                fontSize: '12px',
                padding: '3px 10px',
                borderRadius: '20px',
                background: '#E6F7F1',
                color: '#178A66',
                fontWeight: 600,
              }}
            >
              ● Active patient
            </span>
          </div>

          {/* Key Value List */}
          <div
            style={{
              width: '100%',
              borderTop: '1px solid var(--color-border, #E8ECF1)',
              paddingTop: '8px',
            }}
          >
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                padding: '8px 0',
                borderBottom: '1px solid #F0F2F5',
                fontSize: '12px',
              }}
            >
              <span style={{ color: 'var(--color-text-secondary, #6B7A99)' }}>
                Patient ID
              </span>
              <span
                style={{
                  fontWeight: 600,
                  color: 'var(--color-text-primary, #1A1D26)',
                }}
              >
                #{profile.patientId || '—'}
              </span>
            </div>

            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                padding: '8px 0',
                borderBottom: '1px solid #F0F2F5',
                fontSize: '12px',
              }}
            >
              <span style={{ color: 'var(--color-text-secondary, #6B7A99)' }}>
                Phone
              </span>
              <span
                style={{
                  fontWeight: 600,
                  color: 'var(--color-text-primary, #1A1D26)',
                }}
              >
                {(editing ? form.phoneNumber : profile.phoneNumber) || '—'}
              </span>
            </div>

            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                padding: '8px 0',
                borderBottom: '1px solid #F0F2F5',
                fontSize: '12px',
              }}
            >
              <span style={{ color: 'var(--color-text-secondary, #6B7A99)' }}>
                Blood group
              </span>
              <span
                style={{
                  fontWeight: 600,
                  color: 'var(--color-text-primary, #1A1D26)',
                }}
              >
                {(editing ? form.bloodGroup : profile.bloodGroup) || '—'}
              </span>
            </div>

            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                padding: '8px 0',
                fontSize: '12px',
              }}
            >
              <span style={{ color: 'var(--color-text-secondary, #6B7A99)' }}>
                Date of birth
              </span>
              <span
                style={{
                  fontWeight: 600,
                  color: 'var(--color-text-primary, #1A1D26)',
                }}
              >
                {(editing ? form.dob : profile.dob) || '—'}
              </span>
            </div>
          </div>
        </div>

        {/* ─── RIGHT DETAILS CARD ──────────────────── */}
        <div
          style={{
            flex: 1,
            minWidth: '320px',
            background: '#FFFFFF',
            borderRadius: '12px',
            border: '0.5px solid var(--color-border, #E8ECF1)',
            padding: '24px',
            boxShadow: '0 1px 3px rgba(0,0,0,0.04)',
          }}
        >
          {/* Header Row */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: '24px',
              borderBottom: '1px solid var(--color-border, #E8ECF1)',
              paddingBottom: '16px',
            }}
          >
            <div>
              <h2
                style={{
                  fontSize: '16px',
                  fontWeight: 700,
                  color: 'var(--color-navy, #0B1F3F)',
                  margin: 0,
                }}
              >
                Personal details
              </h2>
              <p
                style={{
                  fontSize: '12px',
                  color: 'var(--color-text-secondary, #6B7A99)',
                  margin: '3px 0 0',
                }}
              >
                Keep your information up to date
              </p>
            </div>

            {!editing ? (
              <button
                type="button"
                onClick={handleEdit}
                style={{
                  background: '#1D9E75',
                  color: '#FFFFFF',
                  border: 'none',
                  borderRadius: '8px',
                  padding: '8px 16px',
                  fontSize: '13px',
                  fontWeight: 600,
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '6px',
                  cursor: 'pointer',
                  transition: 'background 0.15s ease',
                }}
              >
                <IconEdit size={16} />
                Edit profile
              </button>
            ) : (
              <div style={{ display: 'flex', gap: '8px' }}>
                <button
                  type="button"
                  onClick={handleCancel}
                  disabled={saving}
                  style={{
                    background: '#FFFFFF',
                    color: 'var(--color-text-secondary, #6B7A99)',
                    border: '1px solid #E8ECF1',
                    borderRadius: '8px',
                    padding: '8px 16px',
                    fontSize: '13px',
                    fontWeight: 500,
                    cursor: 'pointer',
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '4px',
                  }}
                >
                  <IconX size={16} />
                  Cancel
                </button>
                <button
                  type="button"
                  onClick={handleSave}
                  disabled={saving}
                  style={{
                    background: '#1D9E75',
                    color: '#FFFFFF',
                    border: 'none',
                    borderRadius: '8px',
                    padding: '8px 16px',
                    fontSize: '13px',
                    fontWeight: 600,
                    cursor: 'pointer',
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '6px',
                  }}
                >
                  {saving ? (
                    <>
                      <span className="spinner" /> Saving...
                    </>
                  ) : (
                    'Save changes'
                  )}
                </button>
              </div>
            )}
          </div>

          {/* 2-Column Fields Grid */}
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
              gap: '16px 24px',
              marginBottom: '24px',
            }}
          >
            {/* First Name */}
            <div
              style={{
                borderBottom: '1px solid #F0F2F5',
                paddingBottom: '10px',
              }}
            >
              <label
                style={{
                  display: 'block',
                  fontSize: '11px',
                  fontWeight: 600,
                  color: 'var(--color-text-secondary, #6B7A99)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                  marginBottom: '4px',
                }}
              >
                First name
              </label>
              {editing ? (
                <input
                  className="form-input"
                  value={form.firstName || ''}
                  onChange={set('firstName')}
                  style={{ width: '100%', fontSize: '14px', padding: '6px 10px' }}
                />
              ) : (
                <div style={{ fontSize: '14px', color: '#1A1D26' }}>
                  {profile.firstName || '—'}
                </div>
              )}
            </div>

            {/* Last Name */}
            <div
              style={{
                borderBottom: '1px solid #F0F2F5',
                paddingBottom: '10px',
              }}
            >
              <label
                style={{
                  display: 'block',
                  fontSize: '11px',
                  fontWeight: 600,
                  color: 'var(--color-text-secondary, #6B7A99)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                  marginBottom: '4px',
                }}
              >
                Last name
              </label>
              {editing ? (
                <input
                  className="form-input"
                  value={form.lastName || ''}
                  onChange={set('lastName')}
                  style={{ width: '100%', fontSize: '14px', padding: '6px 10px' }}
                />
              ) : (
                <div style={{ fontSize: '14px', color: '#1A1D26' }}>
                  {profile.lastName || '—'}
                </div>
              )}
            </div>

            {/* Date of Birth */}
            <div
              style={{
                borderBottom: '1px solid #F0F2F5',
                paddingBottom: '10px',
              }}
            >
              <label
                style={{
                  display: 'block',
                  fontSize: '11px',
                  fontWeight: 600,
                  color: 'var(--color-text-secondary, #6B7A99)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                  marginBottom: '4px',
                }}
              >
                Date of birth
              </label>
              {editing ? (
                <input
                  className="form-input"
                  type="date"
                  value={form.dob || ''}
                  onChange={set('dob')}
                  style={{ width: '100%', fontSize: '14px', padding: '6px 10px' }}
                />
              ) : (
                <div style={{ fontSize: '14px', color: '#1A1D26' }}>
                  {profile.dob || '—'}
                </div>
              )}
            </div>

            {/* Blood Group */}
            <div
              style={{
                borderBottom: '1px solid #F0F2F5',
                paddingBottom: '10px',
              }}
            >
              <label
                style={{
                  display: 'block',
                  fontSize: '11px',
                  fontWeight: 600,
                  color: 'var(--color-text-secondary, #6B7A99)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                  marginBottom: '4px',
                }}
              >
                Blood group
              </label>
              {editing ? (
                <select
                  className="form-select"
                  value={form.bloodGroup || ''}
                  onChange={set('bloodGroup')}
                  style={{ width: '100%', fontSize: '14px', padding: '6px 10px' }}
                >
                  <option value="">— Select —</option>
                  {BLOOD_GROUPS.map((bg) => (
                    <option key={bg} value={bg}>
                      {bg}
                    </option>
                  ))}
                </select>
              ) : (
                <div style={{ fontSize: '14px', color: '#1A1D26' }}>
                  {profile.bloodGroup || '—'}
                </div>
              )}
            </div>

            {/* Address (full width span) */}
            <div
              style={{
                gridColumn: '1 / -1',
                borderBottom: '1px solid #F0F2F5',
                paddingBottom: '10px',
              }}
            >
              <label
                style={{
                  display: 'block',
                  fontSize: '11px',
                  fontWeight: 600,
                  color: 'var(--color-text-secondary, #6B7A99)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                  marginBottom: '4px',
                }}
              >
                Address
              </label>
              {editing ? (
                <input
                  className="form-input"
                  value={form.address || ''}
                  onChange={set('address')}
                  style={{ width: '100%', fontSize: '14px', padding: '6px 10px' }}
                />
              ) : (
                <div style={{ fontSize: '14px', color: '#1A1D26' }}>
                  {profile.address || '—'}
                </div>
              )}
            </div>
          </div>

          {/* Emergency Contact Section */}
          <div style={{ marginBottom: '24px' }}>
            <label
              style={{
                display: 'block',
                fontSize: '11px',
                fontWeight: 600,
                color: 'var(--color-text-secondary, #6B7A99)',
                textTransform: 'uppercase',
                letterSpacing: '0.5px',
                marginBottom: '8px',
              }}
            >
              Emergency contact
            </label>
            <div
              style={{
                background: '#F8FAFC',
                borderRadius: '10px',
                border: '1px solid #E8ECF1',
                padding: '16px',
              }}
            >
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
                  gap: '16px',
                }}
              >
                <div>
                  <div
                    style={{
                      fontSize: '11px',
                      color: 'var(--color-text-secondary, #6B7A99)',
                      marginBottom: '4px',
                    }}
                  >
                    Name
                  </div>
                  {editing ? (
                    <input
                      className="form-input"
                      value={form.emergencyContactName || ''}
                      onChange={set('emergencyContactName')}
                      style={{ width: '100%', fontSize: '13px' }}
                    />
                  ) : (
                    <div style={{ fontSize: '14px', fontWeight: 500, color: '#1A1D26' }}>
                      {profile.emergencyContactName || '—'}
                    </div>
                  )}
                </div>

                <div>
                  <div
                    style={{
                      fontSize: '11px',
                      color: 'var(--color-text-secondary, #6B7A99)',
                      marginBottom: '4px',
                    }}
                  >
                    Number
                  </div>
                  {editing ? (
                    <input
                      className="form-input"
                      value={form.emergencyContactNumber || ''}
                      onChange={set('emergencyContactNumber')}
                      style={{ width: '100%', fontSize: '13px' }}
                    />
                  ) : (
                    <div style={{ fontSize: '14px', fontWeight: 500, color: '#1A1D26' }}>
                      {profile.emergencyContactNumber || '—'}
                    </div>
                  )}
                </div>

                <div>
                  <div
                    style={{
                      fontSize: '11px',
                      color: 'var(--color-text-secondary, #6B7A99)',
                      marginBottom: '4px',
                    }}
                  >
                    Relation
                  </div>
                  {editing ? (
                    <input
                      className="form-input"
                      value={form.emergencyContactRelation || ''}
                      onChange={set('emergencyContactRelation')}
                      style={{ width: '100%', fontSize: '13px' }}
                    />
                  ) : (
                    <div style={{ fontSize: '14px', fontWeight: 500, color: '#1A1D26' }}>
                      {profile.emergencyContactRelation || '—'}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* About Section */}
          <div>
            <label
              style={{
                display: 'block',
                fontSize: '11px',
                fontWeight: 600,
                color: 'var(--color-text-secondary, #6B7A99)',
                textTransform: 'uppercase',
                letterSpacing: '0.5px',
                marginBottom: '8px',
              }}
            >
              About / Description
            </label>
            {editing ? (
              <textarea
                className="form-textarea"
                value={form.description || ''}
                onChange={set('description')}
                style={{
                  width: '100%',
                  fontSize: '13px',
                  minHeight: '80px',
                  lineHeight: '1.5',
                  resize: 'none',
                }}
              />
            ) : (
              <div
                style={{
                  fontSize: '13px',
                  color: '#4B5563',
                  lineHeight: '1.6',
                  whiteSpace: 'pre-line',
                }}
              >
                {profile.description || 'No description added yet.'}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import patientAxios from '../api/patientAxios';
import PaginatedTable from '../../admin/components/PaginatedTable';
import PaymentDetailModal from '../../components/PaymentDetailModal';
import { formatCurrency, formatDate } from '../../utils/formatUtils';

export default function PatientPaymentsPage() {
  const [payments, setPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [totalElements, setTotalElements] = useState(0);
  const size = 10;

  const [selectedPaymentId, setSelectedPaymentId] = useState(null);

  const fetchPayments = useCallback(async (pageNum) => {
    try {
      const res = await patientAxios.get(`/payment/history?page=${pageNum}&size=${size}`);
      const data = res.data;
      setPayments(data.content || []);
      setTotalPages(data.totalPages || 0);
      setTotalElements(data.totalElements || 0);
    } catch (err) {
      console.error('Error fetching payment history:', err);
    } finally {
      setLoading(false);
    }
  }, [size]);

  useEffect(() => {
    fetchPayments(page);
  }, [page, fetchPayments]);

  const columns = [
    { header: 'Receipt No.', width: '160px' },
    { header: 'Doctor ID', width: '120px' },
    { header: 'Date', width: '180px' },
    { header: 'Amount', width: '120px' },
    { header: 'Status', width: '130px' },
  ];

  const renderStatusPill = (status) => {
    const s = (status || '').toUpperCase();
    let className = 'status-pill gray';
    if (s === 'SUCCESS') className = 'status-pill green';
    else if (s === 'PENDING') className = 'status-pill amber';
    else if (s === 'FAILED') className = 'status-pill red';
    else if (s === 'REFUNDED') className = 'status-pill gray';

    return <span className={className}>{s || 'PENDING'}</span>;
  };

  const renderRow = (row) => (
    <tr key={row.paymentId}>
      <td>
        <button
          className="link-btn font-mono"
          onClick={() => setSelectedPaymentId(row.paymentId)}
          style={{
            background: 'none',
            border: 'none',
            color: '#1D9E75',
            fontWeight: 600,
            cursor: 'pointer',
            padding: 0,
            textDecoration: 'underline',
          }}
        >
          {row.receiptNumber || `PAY-${row.paymentId}`}
        </button>
      </td>
      <td>{row.doctorName || 'Unknown doctor'}</td>
      <td>{formatDate(row.paidAt || row.createdAt)}</td>
      <td style={{ fontWeight: 600, color: '#0B1F3F' }}>
        {formatCurrency(row.amount)}
      </td>
      <td>{renderStatusPill(row.paymentStatus)}</td>
    </tr>
  );

  return (
    <div style={{ padding: '28px 20px', maxWidth: '1200px', margin: '0 auto' }}>
      <div style={{ marginBottom: '20px' }}>
        <h2 style={{ margin: '0 0 6px', fontSize: '22px', fontWeight: 700, color: '#0B1F3F' }}>
          My Payment History
        </h2>
        <p style={{ margin: 0, fontSize: '13px', color: '#6B7690' }}>
          Track and view receipt details for all your consultation payments
        </p>
      </div>

      <PaginatedTable
        columns={columns}
        data={payments}
        page={page}
        totalPages={totalPages}
        totalElements={totalElements}
        size={size}
        onPageChange={(newPage) => setPage(newPage)}
        loading={loading}
        emptyMessage="No payments yet."
        renderRow={renderRow}
      />

      {selectedPaymentId && (
        <PaymentDetailModal
          paymentId={selectedPaymentId}
          onClose={() => setSelectedPaymentId(null)}
        />
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  IconCheck,
  IconLock,
  IconAlertTriangle,
  IconCalendar,
  IconClock,
  IconReceipt,
  IconStethoscope,
  IconShieldCheck,
  IconArrowLeft,
  IconRefresh,
} from '@tabler/icons-react';
import patientAxios from '../api/patientAxios';
import { formatCurrency } from '../../utils/formatUtils';
import './PaymentPage.css';

// Load Razorpay script dynamically
const loadRazorpayScript = () => {
  return new Promise((resolve) => {
    if (window.Razorpay) {
      resolve(true);
      return;
    }
    const script = document.createElement('script');
    script.src = 'https://checkout.razorpay.com/v1/checkout.js';
    script.onload = () => resolve(true);
    script.onerror = () => resolve(false);
    document.body.appendChild(script);
  });
};

export default function PaymentPage() {
  const location = useLocation();
  const navigate = useNavigate();

  const {
    appointmentId,
    doctorName = 'Consulting Doctor',
    appointmentDate,
    startTime,
  } = location.state || {};

  // UI state machine: 'init' | 'ready' | 'processing' | 'success' | 'failure'
  const [phase, setPhase] = useState('init');
  const [order, setOrder] = useState(null); // CreateOrderResponseDTO
  const [, setVerify] = useState(null);
  const [lastPaymentId, setLastPaymentId] = useState(null);
  const [initError, setInitError] = useState(null);
  const [failureInfo, setFailureInfo] = useState(null);

  // Step 1: Create Order on Mount
  const createOrder = useCallback(async () => {
    if (!appointmentId) {
      setInitError('No appointment selected. Please navigate from booking.');
      return;
    }
    try {
      const res = await patientAxios.post('/payment/create-order', { appointmentId });
      setOrder(res.data);
      setPhase('ready');
    } catch (err) {
      const msg = err.response?.data?.message || err.message || '';
      if (msg.toLowerCase().includes('already done') || msg.toLowerCase().includes('already paid')) {
        setPhase('success');
        return;
      }
      const status = err.response?.status;
      if (status === 401) {
        setInitError('Your session has expired. Please log in again.');
        setTimeout(() => {
          localStorage.clear();
          navigate('/login');
        }, 2000);
        return;
      }
      if (status === 403) {
        setInitError(msg || 'Access denied. You are not authorized to pay for this appointment.');
        return;
      }
      setInitError(msg || 'Failed to create payment order. Please try again.');
    }
  }, [appointmentId, navigate]);

  useEffect(() => {
    createOrder();
  }, [createOrder]);

  // Step 2: Launch Razorpay Checkout
  const openCheckout = async () => {
    if (!order) return;
    const loaded = await loadRazorpayScript();
    if (!loaded) {
      alert('Razorpay SDK failed to load. Please check your network connection.');
      return;
    }

    const options = {
      key: order.razorpayKey,
      order_id: order.razorpayOrderId,
      name: 'Hospital Management System',
      description: `Consultation Fee for ${doctorName}`,
      receipt: order.receiptNumber,
      amount: Math.round(Number(order.amount) * 100),
      currency: order.currency || 'INR',
      theme: { color: '#1D9E75' },

      handler: async (response) => {
        setPhase('processing');
        setLastPaymentId(response.razorpay_payment_id);
        try {
          const vRes = await patientAxios.post('/payment/verify', {
            razorpayPaymentId: response.razorpay_payment_id,
            razorpayOrderId: response.razorpay_order_id,
            razorpaySignature: response.razorpay_signature,
          });
          setVerify(vRes.data);
          setPhase('success');
        } catch (err) {
          setFailureInfo({
            reason: 'Payment verification failed on server.',
            code: 'VERIFY_FAILED',
            description: err.response?.data?.message || 'Please try again or contact support.',
          });
          setPhase('failure');
        }
      },

      modal: {
        ondismiss: () => {
          setFailureInfo({
            reason: 'Payment window was closed before completion.',
            code: 'MODAL_DISMISSED',
            description: 'No charge was made. You can retry using the same order.',
          });
          setPhase('failure');
        },
      },
    };

    try {
      const rzp = new window.Razorpay(options);
      rzp.open();
    } catch (e) {
      console.error('Razorpay open error:', e);
    }
  };

  return (
    <div className="payment-page-root">
      <div className="payment-container">
        {/* Back Link */}
        <button className="back-link-btn" onClick={() => navigate('/my-appointments')}>
          <IconArrowLeft size={16} /> Back to My Appointments
        </button>

        {/* ── STATE 0: INITIAL ERROR ─────────────────── */}
        {initError ? (
          <div className="payment-card error-card">
            <div className="card-header-icon error-icon">
              <IconAlertTriangle size={32} />
            </div>
            <h2>Unable to Proceed</h2>
            <p className="error-msg-text">{initError}</p>
            <button className="primary-teal-btn" onClick={() => navigate('/find-doctors')}>
              Book New Appointment
            </button>
          </div>
        ) : phase === 'init' ? (
          /* ── LOADING INITIAL ORDER ─────────────────── */
          <div className="payment-card loading-card">
            <div className="payment-spinner" />
            <p>Initializing payment order...</p>
          </div>
        ) : phase === 'ready' ? (
          /* ── STATE 1: READY TO PAY ─────────────────── */
          <div className="payment-card">
            <div className="payment-card-header">
              <h2>Confirm & Pay</h2>
              <p className="subtitle">Review your appointment summary before completing payment</p>
            </div>

            {/* Summary Card bg #F7F9FC */}
            <div className="appointment-summary-card">
              <div className="summary-row">
                <IconStethoscope size={18} className="summary-icon" />
                <div className="summary-info">
                  <span className="summary-label">Doctor</span>
                  <span className="summary-val">{doctorName}</span>
                </div>
              </div>

              {(appointmentDate || startTime) && (
                <div className="summary-row">
                  <IconCalendar size={18} className="summary-icon" />
                  <div className="summary-info">
                    <span className="summary-label">Date & Time</span>
                    <span className="summary-val">
                      {appointmentDate || 'Today'} {startTime ? `at ${startTime}` : ''}
                    </span>
                  </div>
                </div>
              )}

              <div className="summary-row">
                <IconReceipt size={18} className="summary-icon" />
                <div className="summary-info">
                  <span className="summary-label">Receipt No.</span>
                  <span className="summary-val font-mono">{order?.receiptNumber || '—'}</span>
                </div>
              </div>
            </div>

            {/* Amount Payable */}
            <div className="amount-payable-block">
              <span className="payable-label">Amount Payable</span>
              <span className="payable-amount">{formatCurrency(order?.amount)}</span>
            </div>

            {/* Pay Button */}
            <button className="pay-now-btn" onClick={openCheckout}>
              <IconLock size={18} />
              Pay {formatCurrency(order?.amount)} Now
            </button>

            <div className="security-caption">
              <IconShieldCheck size={16} /> Secured by Razorpay 256-bit Encryption
            </div>
          </div>
        ) : phase === 'processing' ? (
          /* ── STATE 2: PROCESSING / VERIFYING ───────── */
          <div className="payment-card processing-card">
            <div className="payment-spinner large" />
            <h2>Verifying Your Payment</h2>
            <p>Please wait while we confirm your transaction. Don't close this window.</p>
          </div>
        ) : phase === 'success' ? (
          /* ── STATE 3: PAYMENT SUCCESSFUL ────────────── */
          <div className="payment-card success-card">
            <div className="card-header-icon success-icon">
              <IconCheck size={36} />
            </div>
            <h2>Payment Successful!</h2>
            <p className="success-sub">
              <strong>{formatCurrency(order?.amount)}</strong> paid to {doctorName}
            </p>

            <div className="verify-summary-block">
              <div className="v-row">
                <span>Receipt Number:</span>
                <span className="font-mono">{order?.receiptNumber || '—'}</span>
              </div>
              <div className="v-row">
                <span>Payment ID:</span>
                <span className="font-mono">{lastPaymentId || 'Completed'}</span>
              </div>
            </div>

            <button className="navy-btn" onClick={() => navigate('/my-appointments')}>
              View Appointment
            </button>
          </div>
        ) : phase === 'failure' ? (
          /* ── STATE 4: FAILED / DISMISSED ───────────── */
          <div className="payment-card failure-card">
            <div className="card-header-icon failure-icon">
              <IconAlertTriangle size={32} />
            </div>
            <h2>Payment Not Completed</h2>
            <p className="failure-desc">{failureInfo?.reason || 'The transaction was cancelled or incomplete.'}</p>

            {/* Retry uses the SAME order */}
            <button className="pay-now-btn" onClick={openCheckout}>
              <IconRefresh size={18} /> Try Again ({formatCurrency(order?.amount)})
            </button>
          </div>
        ) : null}
      </div>
    </div>
  );
}
